"""Write docs/01-semantic-model.md from scripts/model_def.py, so the model reference never drifts from the model.

Usage:  python scripts/document_model.py
"""
import collections, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import model_def as M  # noqa: E402

OUT = os.path.join(HERE, '..', 'docs', '01-semantic-model.md')
L = ['# Semantic model reference', '',
     '> Generated by `scripts/document_model.py` from `scripts/model_def.py`. Do not edit by hand.', '',
     f'**{len(M.TABLES)} tables · {len(M.MEAS)} measures · {len(M.RELATIONSHIPS)} relationships** · import mode · culture en-CA · '
     'fiscal year April-March named by the year it ends.', '',
     '## Star schema', '', '```mermaid', 'erDiagram']
for ft, fc, tt, tc in M.RELATIONSHIPS:
    L.append(f'    {tt.upper()} ||--o{{ {ft.upper()} : "{tc}"')
L += ['```', '',
      'All relationships are many-to-one, single direction, from the `GL` fact to its dimensions. '
      'Report-line, selector and bridge tables are deliberately disconnected: measures apply them with `TREATAS` or `SELECTEDVALUE`, '
      'which is the Goodly "template table" pattern for financial statements.', '',
      '## Power Query', '',
      'Every query reads through one static source, `Folder.Files(DataRoot)`, and filters to the subfolder it needs. '
      'That keeps refresh free of privacy-level prompts and gateway requirements, and makes adding or removing a period a file operation.', '',
      '| Function | Purpose |', '|---|---|',
      '| `fnReadCsv(subfolder, fileName)` | One UTF-8 CSV; blank strings become null |',
      '| `fnLoadLedgerFolder(subfolder, scenario)` | Every `GL_*.csv` in a folder: columns matched by name (handles schema drift), exact duplicates removed, blank department mapped to 0 "Unassigned" |', '',
      '## Tables', '']
for t in M.TABLES:
    kind = 'calculated (DAX)' if 'dax' in t else 'Power Query'
    L += [f"### {t['name']}" + (' (hidden)' if t.get('hidden') else ''), '', f"{t.get('desc', '')} *Source: {kind}.*", '',
          '| Column | Type | Notes |', '|---|---|---|']
    for cn, dt, p in t['cols']:
        notes = []
        if 'expr' in p: notes.append('calculated')
        if p.get('hidden'): notes.append('hidden')
        if p.get('sortBy'): notes.append(f"sorted by {p['sortBy']}")
        if p.get('desc'): notes.append(p['desc'])
        L.append(f"| {cn} | {dt} | {'; '.join(notes)} |")
    L.append('')
    if t['name'] == 'Report Line':
        L += ['| Key | Line | Type | Accounts |', '|---|---|---|---|']
        for key, name, sec, typ, stmt, accts in M.LINES:
            L.append(f"| {key} | {name} | {typ} | {', '.join(map(str, accts))} |")
        L.append('')
L += ['## Measures', '', 'Conventions: costs are stored negative, so every variance is "actual minus budget" and **positive is always favourable**. '
      'Period measures follow the **Period View** selector (MTD/QTD/YTD) and the **Selected Month**, which defaults to the latest closed month.', '']
folders = collections.OrderedDict()
for m in M.MEAS:
    folders.setdefault(m['folder'], []).append(m)
for f, ms in folders.items():
    L += [f'### {f}', '']
    for m in ms:
        L.append(f"**{m['name']}**" + (f" · format `{m['fmt']}`" if m.get('fmt') else '') + (f"  \n{m['desc']}" if m.get('desc') else ''))
        L += ['```dax', m['expr'], '```', '']
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, 'w', encoding='utf-8') as fh:
    fh.write('\n'.join(L) + '\n')
print('wrote', os.path.relpath(OUT), len(M.MEAS), 'measures')
